  let prefix = 1;
  for (let i = 0; i < nums.length; i++) {
    result[i] = prefix;
    prefix *= nums[i];
  }
  let suffix = 1;
  for (let i = nums.length - 1; i >= 0; i--) {
    result[i] *= suffix;
    suffix *= nums[i];
  }
  return result;
}

const [n, ...nums] = input.trim().split(/\s+/).map(Number);
console.log(productExceptSelf(nums.slice(0, n)).join(" "));

