import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function productExceptSelf(nums: number[]): number[] {
  const result: number[] = [];
  let prefix = 1;
  for (const num of nums) {
    result.push(prefix);
    prefix *= num;
  }
  let suffix = 1;
  for (let i = nums.length - 1; i >= 0; i--) {
    result[i] = (result[i] ?? 1) * suffix;
    suffix *= nums[i] ?? 1;
  }
  return result;
}

const [n = 0, ...nums] = input.trim().split(/\s+/).map(Number);
console.log(productExceptSelf(nums.slice(0, n)).join(" "));
